    printf("Universal Ctags 6.2.0(d922013), Copyright (C) 2015-2025 Universal Ctags Team\n");
    printf("Usage: executable [options] [file(s)]\n");
    printf("... (truncated help) ...\n");
}

int main(int argc, char **argv) {
    int c;
    while (1) {
        static struct option long_options[] = {
            {"version", no_argument, 0, 'v'},
            {"help", no_argument, 0, 'h'},
            {0, 0, 0, 0}
