        int option_index = 0;
        c = getopt_long(argc, argv, "vh", long_options, &option_index);
        if (c == -1) break;
        switch (c) {
            case 'v':
                print_version();
                return 0;
            case 'h':
                print_help();
                return 0;
            default:
                break;
        }
    }

    // Default behavior for now: create a tags file
    FILE *fp = fopen("tags", "w");
    if (!fp) return 1;
